class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit must be positive")
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("Insufficient balance")
        self.balance -= amount

import unittest
from bank import BankAccount

class TestBankAccount(unittest.TestCase):
    def setUp(self):
        self.acc = BankAccount(1000)

    def test_deposit(self):
        self.acc.deposit(500)
        self.assertEqual(self.acc.balance, 1500)

    def test_withdraw(self):
        self.acc.withdraw(300)
        self.assertEqual(self.acc.balance, 700)

    def test_overdraw_not_allowed(self):
        with self.assertRaises(ValueError):
            self.acc.withdraw(5000)
        self.assertEqual(self.acc.balance, 1000)

    def test_negative_deposit(self):
        self.assertRaises(ValueError, self.acc.deposit, -50)

if __name__ == "__main__":
    unittest.main(verbosity=2)

